import type { Metadata } from "next";
import { APP_NAME } from "@/constants";

/** Canonical origin. Set NEXT_PUBLIC_SITE_URL when a custom domain is added. */
export const SITE_URL = (process.env.NEXT_PUBLIC_SITE_URL?.trim() || "https://vektoraha.vercel.app").replace(/\/$/, "");

export const SITE_DESCRIPTION =
  "Ubah foto jadi karakter anime atau pasfoto studio profesional untuk lamaran kerja secara online dan gratis. Latar merah, biru, atau putih, ukuran 2×3, 3×4, 4×6, siap cetak 300 dpi.";

/** Shared social preview generated by app/opengraph-image.tsx */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: "VektorAha — Pasfoto online & ubah foto jadi anime dengan AI",
};

export const SITE_KEYWORDS = [
  "pasfoto online",
  "pasfoto latar merah",
  "pasfoto latar biru",
  "pas foto 3x4",
  "pas foto 4x6",
  "foto lamaran kerja",
  "ganti background foto",
  "ubah foto jadi anime",
  "foto anime AI",
  "edit foto AI gratis",
];

interface PageSeo {
  title: string;
  description: string;
  path: `/${string}`;
  keywords?: string[];
}

/** Per-page metadata with canonical URL, Open Graph and Twitter cards. */
export function pageMetadata({ title, description, path, keywords }: PageSeo): Metadata {
  return {
    title,
    description,
    keywords: keywords ?? SITE_KEYWORDS,
    alternates: { canonical: path },
    openGraph: {
      type: "website",
      locale: "id_ID",
      siteName: APP_NAME,
      url: path,
      title: `${title} · ${APP_NAME}`,
      description,
      images: [OG_IMAGE],
    },
    twitter: { card: "summary_large_image", title: `${title} · ${APP_NAME}`, description, images: [OG_IMAGE.url] },
  };
}
